"""Reviewed rotated source tables 157/159/160. No unresolved numeric cells are invented."""
import copy
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
path=ROOT/'scripts/atlas/corrections/a97001.json'
data=json.loads(path.read_text(encoding='utf-8'))
pages={p['page']:(s['id'],p) for f in (ROOT/'data/atlas/a97001/sections').glob('*.json')
       for s in [json.loads(f.read_text(encoding='utf-8'))] for p in s['pages']}

def table(page,index,changes,ids):
    obj=pages[page][1]['tables'][index]
    cells=copy.deepcopy(obj['cells'])
    for row,col,he,ru in changes:
        cell=next(c for c in cells if c['row']==row and c['col']==col)
        cell.update(he=he,ru=ru)
    data['structure'].append({'page':page,'section':pages[page][0],'op':'set','collection':'tables',
                             'id':obj['id'],'fields':{'cells':cells},'audit_ids':ids,
                             'why':'Сверка повёрнутой исходной таблицы PDF; исправлены читаемые фрагменты, нечитаемые не восстановлены догадкой'})

